 let n=0;const {client,calls}=await fixture(async()=>{if(++n===1)return json({ok:false,code:'INTERNAL_ERROR'},500);if(n===2)throw Error('private-draft-secret');if(n===3)return json({ok:false,code:'NOT_AVAILABLE'},404);const state=client.paidSimpleDraftState(tenant);if(state.phase==='ready')throw Error('fixture requires draft');return json({ok:true,data:{flowId:state.flowId,revision:1,serviceId,name:'Current persisted draft',presentation:{accentColor:'#0f766e',layout:'stacked'}}});});await client.publishPaidSimple(tenant,other,{serviceId,name:'Unverified publication',checkoutOrigin:STAGING_CHECKOUT_ORIGIN}).catch(()=>{});const publication=client.paidSimplePublicationState(tenant);const first=render(<PaidSimplePublisher client={client} tenantId={tenant} role="BUSINESS_OWNER" services={[service]} staging/>);fillDraft();fireEvent.click(visibleAction({name:'Save draft'}));await screen.findByText(/Draft save status is unverified/);const id=(screen.getByLabelText('Draft ID') as HTMLInputElement).value;expect(visibleAction({name:'Save draft'})).toBeDisabled();first.unmount();render(<PaidSimplePublisher client={client} tenantId={tenant} role="BUSINESS_OWNER" services={[service]} staging/>);expect(screen.getByLabelText('Draft ID')).toHaveValue(id);expect(screen.getByLabelText('Draft ID')).toHaveAttribute('readonly');fireEvent.click(visibleAction({name:'Load draft'}));await screen.findByText(/This draft is unavailable/);expect(visibleAction({name:'Save draft'})).toBeDisabled();expect(client.paidSimplePublicationState(tenant)).toEqual(publication);fireEvent.click(visibleAction({name:'Load draft'}));await screen.findByText(/Current draft revision 1 loaded/);expect(screen.getByLabelText('Draft name')).toHaveValue('Current persisted draft');expect(visibleAction({name:'Save draft'})).toBeEnabled();expect(client.paidSimplePublicationState(tenant)).toEqual(publication);expect(calls).toHaveBeenCalledTimes(6);expect(calls.mock.calls[4]?.[1]?.method).toBe('GET');expect(calls.mock.calls[5]?.[1]?.method).toBe('GET');expect(document.body.textContent).not.toContain('private-draft-secret');expect(screen.queryByText('Staging form published')).toBeNull();
