it('upgrades fields only explicitly, rejects invalid condition before save, and performs no automatic network on editor or preview',async()=>{const {client,calls}=await fixture(async()=>{throw Error('unexpected');});render(<PaidSimplePublisher client={client} tenantId={tenant} role="BUSINESS_OWNER" services={[service]} staging/>);fillDraft();addInformation();fireEvent.click(screen.getByRole('button',{name:'Add text field'}));fireEvent.change(screen.getByRole('textbox',{name:'Field 2 label'}),{target:{value:'Location'}});fireEvent.click(screen.getByRole('button',{name:'Enable conditional informational fields'}));fireEvent.change(screen.getByRole('combobox',{name:'Show conditional field 2 when'}),{target:{value:'custom_field_1'}});fireEvent.click(screen.getByRole('button',{name:'Save draft'}));expect(screen.getByText(/Fix the informational text fields before saving/)).toBeVisible();expect(calls).toHaveBeenCalledTimes(2);openTab('Preview');fireEvent.click(screen.getByRole('button',{name:'Preview draft presentation'}));expect(screen.getByText(/Fix the conditional draft configuration/)).toBeVisible();expect(calls).toHaveBeenCalledTimes(2);});
it('publishes render6 only through its explicit dedicated action and preserves lost receipt across remount until exact GET recovery',async()=>{let n=0;const {client,calls}=await fixture(async()=>++n===1?json({ok:true,data:conditionalUiDraft}):n===2?json({ok:false,code:'INTERNAL_ERROR'},500):n===3?json({ok:true,data:{...conditionalUiReceipt,draftRevision:4}}):json({ok:true,data:conditionalUiReceipt}));const first=render(<PaidSimplePublisher client={client} tenantId={tenant} role="BUSINESS_OWNER" services={[service]} staging conditionalPublicationAvailable/>);fireEvent.change(screen.getByLabelText('Draft ID'),{target:{value:other}});fireEvent.click(screen.getByRole('button',{name:'Load draft'}));await screen.findByText(/Current draft revision 3 loaded/);openTab('Publish');fireEvent.click(screen.getByRole('button',{name:'Publish saved conditional fields'}));await waitFor(()=>expect(client.paidConditionalPublicationState(tenant).phase).toBe('unknown'));expect(screen.getByRole('button',{name:'Save draft'})).toBeDisabled();expect(screen.getByRole('button',{name:'Load draft'})).toBeDisabled();first.unmount();render(<PaidSimplePublisher client={client} tenantId={tenant} role="BUSINESS_OWNER" services={[service]} staging conditionalPublicationAvailable/>);expect(calls).toHaveBeenCalledTimes(4);openTab('Publish');fireEvent.click(screen.getByRole('button',{name:'Check conditional publication receipt'}));await waitFor(()=>expect(calls).toHaveBeenCalledTimes(5));expect(client.paidConditionalPublicationState(tenant).phase).toBe('unknown');fireEvent.click(screen.getByRole('button',{name:'Check conditional publication receipt'}));await screen.findByRole('link',{name:'Open published conditional-field booking form'});expect(screen.getByRole('link',{name:'Open published conditional-field booking form'})).toHaveAttribute('href',STAGING_CHECKOUT_ORIGIN+conditionalUiReceipt.publication.hostedPath);expect(calls.mock.calls.slice(2).map(([,init])=>init?.method)).toEqual(['GET','POST','GET','GET']);expect(client.paidCustomerFieldPublicationState(tenant)).toEqual({phase:'ready'});openTab('Install & Health');expect(screen.getByRole('link',{name:'Open last verified conditional booking form'})).toHaveAttribute('href',STAGING_CHECKOUT_ORIGIN+conditionalUiReceipt.publication.hostedPath);expect(screen.getByLabelText('Conditional website iframe code')).toHaveAttribute('readonly');expect(screen.getByText(/Conditional history and rollback evidence are unavailable/)).toBeVisible();expect(document.body.textContent).not.toContain('synthetic-owner-private-token');});
it('drops a late conditional publication receipt after selected business changes without exposing prior metadata or issuing another request',async()=>{let finish!:(value:Response)=>void;let n=0;const {client,calls}=await fixture(async()=>++n===1?json({ok:true,data:conditionalUiDraft}):new Promise(resolve=>finish=resolve));const view=render(<PaidSimplePublisher client={client} tenantId={tenant} role="BUSINESS_OWNER" services={[service]} staging conditionalPublicationAvailable/>);fireEvent.change(screen.getByLabelText('Draft ID'),{target:{value:other}});fireEvent.click(screen.getByRole('button',{name:'Load draft'}));await screen.findByText(/Current draft revision 3 loaded/);openTab('Publish');fireEvent.click(screen.getByRole('button',{name:'Publish saved conditional fields'}));view.rerender(<PaidSimplePublisher client={client} tenantId={other} role="BUSINESS_OWNER" services={[{...service,tenant_id:other}]} staging conditionalPublicationAvailable/>);finish(json({ok:true,data:conditionalUiReceipt}));await waitFor(()=>expect(client.paidConditionalPublicationState(tenant).phase).toBe('published'));expect(screen.queryByRole('link',{name:'Open published conditional-field booking form'})).toBeNull();expect(calls).toHaveBeenCalledTimes(4);});
